const sum = values=>values.reduce((a,b)=>a+b,0);
export function normalize(weights){const safe=weights.map(v=>Math.max(0,Number(v)||0));const total=sum(safe);return safe.map(v=>total?v/total:0)}
export function largestRemainder(weights,count){const n=Math.max(0,Math.floor(Number(count)||0));const p=normalize(weights);if(!p.length || !sum(p)) return p.map(()=>0);const raw=p.map(w=>w*n),out=raw.map(Math.floor);const order=raw.map((v,i)=>({i,remainder:v-out[i]})).sort((a,b)=>b.remainder-a.remainder||a.i-b.i);for(let i=0;i<n-sum(out);i++)out[order[i%order.length].i]++;return out;}
export function totals(data){return {tickets:sum(data.lotteries.map(x=>x.ticketsPurchased)),wins:sum(data.lotteries.map(x=>x.winningTickets)),winnings:sum(data.lotteries.map(x=>x.winningAmount))};}
export function smartMix(data){const total=totals(data).tickets;if(data.customer.purchaseCount>=3&&total>0)return {origin:'Based on your own ticket purchases',weights:data.lotteries.map(x=>x.ticketsPurchased/total)};const map=data.customer.purchaseCount>0?data.lookalikeMix:data.popularMix;const other=normalize(data.lotteries.map(l=>map[l.name]||0));if(data.customer.purchaseCount>0&&total>0)return {origin:'30% your purchases + 70% lookalike buyers',weights:data.lotteries.map((l,i)=>l.ticketsPurchased/total*.3+other[i]*.7)};return {origin:'Based on popular customer mixes',weights:other};}
export function customMix(data){const t=totals(data);if(data.customer.purchaseCount<3||!t.tickets){const mix=smartMix(data);return {...mix,origin:'Custom bundle uses '+mix.origin.toLowerCase()}};if(!t.wins)return {origin:'No winning tickets: using purchase distribution only',weights:data.lotteries.map(l=>l.ticketsPurchased/t.tickets)};return {origin:'70% share of tickets bought + 30% share of winning tickets',weights:data.lotteries.map(l=>.7*l.ticketsPurchased/t.tickets+.3*l.winningTickets/t.wins)};}
// Illustrative only. Independence and overall win rates have not been verified for real purchases.
export function probability(lotteries,amounts,data,personal=false){return 1-lotteries.reduce((product,l,i)=>{const overall=Number(l.overallWinRate)||0;const k=Number(data.smoothingK)||0;const rate=personal?(l.winningTickets+k*overall)/(l.ticketsPurchased+k||1):overall;return product*Math.pow(1-rate,amounts[i]||0)},1)}
export function nlbEligible(data){return [...data.nlb].filter(l=>l.soldOnWinWay&&data.lotteries.some(x=>x.name===l.name)).sort((a,b)=>b.totalPrizes-a.totalPrizes||a.name.localeCompare(b.name)).slice(0,4)}
